/**
 * Product specification model (forms, grades, packing, logistics).
 *
 * Data lives in data/specs.ts, which is GENERATED by scripts/import-specs.py
 * from the owner's sheet (docs/team/web/site-v2/OWNER-SPEC-SHEET.xlsx).
 * This file holds the types and the helpers the pages use. Never put a value
 * in data/specs.ts that the owner has not supplied or that is not already
 * published on the site: an empty field renders "Confirmed with sales".
 */
import { specs } from '@/data/specs';
import { products } from '@/data/products';

/** Product forms. Codes match the RFQ `productForm` values where the RFQ offers them. */
export const FORM_KINDS = ['fresh_whole', 'fresh_gutted', 'fresh_fillet', 'frozen_whole', 'frozen_gutted', 'frozen_fillet'] as const;
export type FormKind = (typeof FORM_KINDS)[number];

export const GRADE_LABELS = ['small', 'medium', 'large', 'extra_large', 'jumbo'] as const;
export type GradeLabel = (typeof GRADE_LABELS)[number];

export const PACK_TYPES = ['eps_box', 'carton', 'plastic_crate', 'vacuum_pack', 'other'] as const;
export type PackType = (typeof PACK_TYPES)[number];

export const SHIPPING_MODES = ['air', 'reefer_truck', 'sea'] as const;
export type ShippingMode = (typeof SHIPPING_MODES)[number];

export interface Grade {
    label?: GradeLabel;
    /** Weight per piece, grams. min only = "min g and above" */
    minG?: number;
    maxG?: number;
}

export interface ProductFormSpec {
    kind: FormKind;
    grades: Grade[];
    shelfLifeDays?: number;
    /** Storage and transport temperature, °C */
    tempC?: { min: number; max: number };
    packType?: PackType;
    /** Net weight per box, kg */
    netWeightKg?: number;
    /**
     * true = taken from the existing site product list, not yet confirmed by the
     * owner. Rendered with an "indicative" note.
     */
    indicative?: boolean;
}

export interface ShippingModeSpec {
    mode: ShippingMode;
    /** Minimum order for this mode, kg */
    moqKg?: number;
}

export interface PackingLogistics {
    boxType?: PackType;
    /** Outer box dimensions, cm (length x width x height) */
    boxOuterCm?: { l: number; w: number; h: number };
    boxesPerPallet?: number;
    shippingModes: ShippingModeSpec[];
    /** Typical hours from farm/harvest to the plant */
    farmToPlantHours?: number;
    /** Typical hours from the plant to the airport / port / border */
    plantToPortHours?: number;
    /** true = box type comes from the existing product list, not owner-confirmed */
    indicative?: boolean;
}

export interface SpeciesSpec {
    forms: ProductFormSpec[];
    logistics: PackingLogistics;
}

const EMPTY: SpeciesSpec = { forms: [], logistics: { shippingModes: [] } };

export function getSpeciesSpec(slug: string): SpeciesSpec {
    return specs[slug] ?? EMPTY;
}

/** Distinct forms across the published products, in FORM_KINDS order. */
export function publishedFormKinds(): FormKind[] {
    const used = new Set(products.flatMap((p) => getSpeciesSpec(p.slug).forms.map((f) => f.kind)));
    return FORM_KINDS.filter((k) => used.has(k));
}

/** Any real logistics fact (box type alone does not count: it is already shown per form). */
export function hasLogisticsData(l: PackingLogistics): boolean {
    return Boolean(
        l.boxOuterCm || l.boxesPerPallet || l.shippingModes.length || l.farmToPlantHours !== undefined || l.plantToPortHours !== undefined,
    );
}

export function hasAnyLogistics(l: PackingLogistics): boolean {
    return Boolean(l.boxType) || hasLogisticsData(l);
}

export interface Units {
    g: string;
    kg: string;
    /**
     * Wrap the number part in Unicode LTR isolates (U+2066…U+2069) so "200–300"
     * and "500+" keep their order inside Arabic (RTL) text and inputs.
     */
    isolate?: boolean;
}

/** "200–300 g", "500+ g", "1–2 kg", "2+ kg". Western digits, as on the rest of the site. */
export function formatGradeRange(g: Grade, u: Units): string | null {
    const r = gradeRange(g, u);
    if (!r) return null;
    return u.isolate ? `${String.fromCharCode(0x2066)}${r.num}${String.fromCharCode(0x2069)} ${r.unit}` : `${r.num} ${r.unit}`;
}

function gradeRange(g: Grade, u: Units): { num: string; unit: string } | null {
    const { minG, maxG } = g;
    if (minG === undefined && maxG === undefined) return null;
    const useKg = (minG ?? 0) >= 1000 || (maxG !== undefined && maxG >= 1000 && (minG ?? 0) % 1000 === 0 && maxG % 1000 === 0);
    const unit = useKg ? u.kg : u.g;
    const n = (v: number) => String(useKg ? Math.round((v / 1000) * 100) / 100 : v);
    if (minG !== undefined && maxG !== undefined) return { num: `${n(minG)}–${n(maxG)}`, unit };
    if (minG !== undefined) return { num: `${n(minG)}+`, unit };
    return { num: `≤ ${n(maxG!)}`, unit };
}
